# region: render
def render(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
            return out
    return out

# region: gather
def gather(xs, offset=-1):
    return [v + offset for v in xs]

# region: shape
def shape(xs, limit=20):
    return [v if v <= limit else limit for v in xs]

# region: fold
def fold(xs):
    return [v for v in xs if v % 2 == 0]

# region: sift
def sift(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: emit
def emit(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return emit(sift(fold(shape(gather(render(raw))))))

